"use client";

import { useEffect, useState } from "react";

type Order = {
  id: number;
  user_id: number;
  order_status: string;
  total_amount: number;
  order_date: string;
};

export default function OrdersPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [status, setStatus] = useState("all");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/orders")
      .then((res) => res.json())
      .then((data) => setOrders(data));
  }, []);

  const filteredOrders =
    status === "all"
      ? orders
      : orders.filter((order) => order.order_status === status);

  const totalAmount = filteredOrders.reduce(
    (sum, order) => sum + Number(order.total_amount || 0),
    0
  );

  return (
    <main className="page-container orders-page">
      <section className="page-header">
        <h1 className="page-title">Orders</h1>
        <p className="page-subtitle">
          Orange sales and order tracking design.
        </p>
      </section>

      <section className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">🛒</div>
          <p>Total Orders</p>
          <h2>{orders.length}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">✅</div>
          <p>Completed</p>
          <h2>{orders.filter((o) => o.order_status === "completed").length}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">⏳</div>
          <p>Pending</p>
          <h2>{orders.filter((o) => o.order_status === "pending").length}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">₹</div>
          <p>Amount</p>
          <h2>₹{totalAmount.toFixed(2)}</h2>
        </div>
      </section>

      <select
        className="search-box"
        value={status}
        onChange={(e) => setStatus(e.target.value)}
      >
        <option value="all">All Orders</option>
        <option value="completed">Completed</option>
        <option value="pending">Pending</option>
        <option value="processing">Processing</option>
        <option value="cancelled">Cancelled</option>
      </select>

      <section className="table-card">
        <h2>Orders List</h2>
        <p>{filteredOrders.length} records found</p>

        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>User ID</th>
                <th>Status</th>
                <th>Amount</th>
                <th>Date</th>
              </tr>
            </thead>

            <tbody>
              {filteredOrders.map((order) => (
                <tr key={order.id}>
                  <td>{order.id}</td>
                  <td>{order.user_id}</td>
                  <td>{order.order_status}</td>
                  <td>₹{Number(order.total_amount).toFixed(2)}</td>
                  <td>{new Date(order.order_date).toLocaleString("en-IN")}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}